import pypdf,re
for i in [2,4,5,1]:
    t=' '.join(p.extract_text() or '' for p in pypdf.PdfReader(f'studies/papers/paper_{i}.pdf').pages)
    print('=====',i)
    for m in re.finditer(r'tamoxifen|OHT|4-OH|TOT|Tam\b',t,re.I):
        s=t[max(0,m.start()-150):m.end()+150].replace('\n',' ')
        if re.search(r'\d\s*(n|µ|u|μ|m)M|mol',s): print('-',s)

